import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FeedbackDemo {

    private static final Logger log = Logger.getLogger(FeedbackDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Applying PR-size feedback at " + BANK_NAME);

        SizePolicy policy = new SizePolicy(10, 400);
        SizeCheckService checker = new SizeCheckService(policy);

        // The old habit before feedback: one giant PR bundling everything.
        PullRequest oldGiant = new PullRequest("PR-7001",
                "Account creation + transfer + reporting in one change", 28, 1900);

        // The new habit after feedback: three small, reviewable PRs.
        List<PullRequest> newSmall = List.of(
                new PullRequest("PR-7002", "Account creation for SAV2001/CUR3001", 6, 220),
                new PullRequest("PR-7003", "Transfer logic", 7, 300),
                new PullRequest("PR-7004", "Reporting for CUR3001", 5, 180));

        log.warning("BEFORE feedback:");
        checker.check(oldGiant);

        log.info("AFTER feedback (same work, split into reviewable pieces):");
        for (PullRequest pr : newSmall) {
            checker.check(pr);
        }
    }
}

// ─── Would be in model/PullRequest.java in a real project ───
class PullRequest {
    private final String id;
    private final String description;
    private final int filesChanged;
    private final int linesChanged;

    PullRequest(String id, String description, int filesChanged, int linesChanged) {
        this.id = id;
        this.description = description;
        this.filesChanged = filesChanged;
        this.linesChanged = linesChanged;
    }

    String getId() { return id; }
    String getDescription() { return description; }
    int getFilesChanged() { return filesChanged; }
    int getLinesChanged() { return linesChanged; }
}

// ─── Would be in policy/SizePolicy.java in a real project ───
class SizePolicy {
    private final int maxFiles;
    private final int maxLines;

    SizePolicy(int maxFiles, int maxLines) {
        this.maxFiles = maxFiles;
        this.maxLines = maxLines;
    }

    boolean isReviewable(PullRequest pr) {
        return pr.getFilesChanged() <= maxFiles && pr.getLinesChanged() <= maxLines;
    }

    int getMaxFiles() { return maxFiles; }
    int getMaxLines() { return maxLines; }
}

// ─── Would be in service/SizeCheckService.java in a real project ───
class SizeCheckService {
    private static final Logger log = Logger.getLogger(SizeCheckService.class.getName());
    private final SizePolicy policy;

    SizeCheckService(SizePolicy policy) {
        this.policy = policy;
    }

    boolean check(PullRequest pr) {
        boolean ok = policy.isReviewable(pr);
        if (ok) {
            log.info(() -> pr.getId() + " reviewable (" + pr.getFilesChanged()
                    + " files, " + pr.getLinesChanged() + " lines).");
        } else {
            log.warning(() -> pr.getId() + " TOO LARGE (" + pr.getFilesChanged()
                    + " files, " + pr.getLinesChanged() + " lines). Split it to make reviews safe.");
        }
        return ok;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
